        'big := int64(1) << 40      // 1099511627776; the cast must come first',
        'flag := true               // bool',
        'name := "Bengali"          // string: a read-only slice of bytes',
        'initial := name[0]         // byte \'B\' — index gives BYTES',
        '',
        'const (                    // iota makes an enum: 0,1,2',
        '\tStatusNew iota',
