        '\t\ttotal += x',
        '\t}',
        '\treturn total',
        '}',
        '',
        'type Stack []int',
        '',
        'func (s *Stack) Push(v int) {        // pointer receiver: mutates',
        '\t*s = append(*s, v)',
        '}',
